def _compute_agent_net_grid_mw(load_seq_kw:np.ndarray,pv_raw_seq_kw:np.ndarray,battery_charge_mw:np.ndarray,battery_discharge_mw:np.ndarray,pv_curtail_mw:np.ndarray)->np.ndarray:load_seq_kw=np.asarray(load_seq_kw,dtype=np.float32);pv_raw_seq_kw=np.asarray(pv_raw_seq_kw,dtype=np.float32);battery_charge_mw=np.asarray(battery_charge_mw,dtype=np.float32);battery_discharge_mw=np.asarray(battery_discharge_mw,dtype=np.float32);pv_curtail_mw=np.asarray(pv_curtail_mw,dtype=np.float32);return((load_seq_kw-pv_raw_seq_kw)/1e3+battery_charge_mw-battery_discharge_mw+pv_curtail_mw).astype(np.float32)
def _model_size_from_model(model:Any)->ModelSize:return ModelSize(num_vars=int(getattr(model,'NumVars',0)),num_binary_vars=int(getattr(model,'NumBinVars',0)),num_linear_constraints=int(getattr(model,'NumConstrs',0)),num_quadratic_constraints=int(getattr(model,'NumQConstrs',0)))
def _sum_model_sizes(model_sizes:list[ModelSize|None])->ModelSize:valid=[model_size for model_size in model_sizes if model_size is not None];return ModelSize(num_vars=int(sum(model_size.num_vars for model_size in valid)),num_binary_vars=int(sum(model_size.num_binary_vars for model_size in valid)),num_linear_constraints=int(sum(model_size.num_linear_constraints for model_size in valid)),num_quadratic_constraints=int(sum(model_size.num_quadratic_constraints for model_size in valid)))
def _simultaneous_metrics(battery_charge_mw:np.ndarray,battery_discharge_mw:np.ndarray,p_max_mw:np.ndarray,threshold_ratio:float)->tuple[np.ndarray,int,float,float]:simultaneous_kw=(1e3*np.minimum(np.asarray(battery_charge_mw,dtype=np.float32),np.asarray(battery_discharge_mw,dtype=np.float32))).astype(np.float32);threshold_kw=(1e3*float(max(threshold_ratio,.0))*np.asarray(p_max_mw,dtype=np.float32).reshape(-1,1)).astype(np.float32);simultaneous_agent_steps=int(np.count_nonzero(simultaneous_kw>threshold_kw));total_agent_steps=int(simultaneous_kw.shape[0]*simultaneous_kw.shape[1])if simultaneous_kw.ndim==2 else 0;return simultaneous_kw,simultaneous_agent_steps,float(simultaneous_agent_steps)/max(1,total_agent_steps),float(np.max(simultaneous_kw))if simultaneous_kw.size else .0
def _first_step_grid(values:np.ndarray|None,*,scale:float=1.)->np.ndarray|None:return None if values is None else np.asarray(values[:,0]*scale,dtype=np.float32)
def _first_step_scalar(values:np.ndarray|None,*,scale:float=1.)->float:return float('nan')if values is None else float(values[0]*scale)
